const tabId = 1854033397;

const candidateUrls = [
  "https://cookpad.com/eng/recipes/25447752", // Waffle and pancake recipe
  "https://cookpad.com/eng/recipes/25118670", // Cottage Cheese Pancakes
  "https://cookpad.com/eng/recipes/25038175", // Hibiscus pancakes 🥞
  "https://cookpad.com/eng/recipes/24475225", // Cottage Cheese Pancakes
  "https://cookpad.com/eng/recipes/16356152", // Whole wheat pancakes
  "https://cookpad.com/eng/recipes/16833341", // California Farm Lent Pancakes
  "https://cookpad.com/eng/recipes/16811499", // California Farm Buckwheat Pancakes
  "https://cookpad.com/eng/recipes/16950684"  // Bottle guard pancake
];

const recipeDetails = await browserjs(tabId, async (urls) => {
  const data = [];
  for (const url of urls) {
    try {
      const resp = await fetch(url);
      const html = await resp.text();
      const parser = new DOMParser();
      const doc = parser.parseFromString(html, 'text/html');

      const title = doc.querySelector('h1')?.textContent?.trim();
      const description = doc.querySelector('.description, [itemprop="description"]')?.textContent?.trim();
      const ingredients = Array.from(doc.querySelectorAll('.ingredient-item, [itemprop="recipeIngredient"], .ingredient__details, [data-ingredient]'))
        .map(el => el.textContent?.trim().replace(/\s+/g, ' '));

      // Fallback for ingredients if specific classes differ
      let allIngredients = ingredients;
      if (allIngredients.length === 0) {
        const ingContainer = doc.querySelector('#ingredients, .ingredients');
        if (ingContainer) {
          allIngredients = Array.from(ingContainer.querySelectorAll('li, div')).map(el => el.textContent?.trim().replace(/\s+/g, ' ')).filter(Boolean);
        }
      }

      data.push({
        url,
        title,
        description,
        ingredients: allIngredients
      });
    } catch (e) {
      data.push({ url, error: e.message });
    }
  }
  return data;
}, candidateUrls);

console.log(JSON.stringify(recipeDetails, null, 2));

